(() => {
  const id = 'bys-songti-font';
  let s = document.getElementById(id);
  if (!s) { s = document.createElement('style'); s.id = id; document.head.appendChild(s); }
  s.textContent = 'html, body, body *:not(style):not(script) { font-family: "宋体", "SimSun", "Songti SC", "STSong", serif !important; }';
  const h1 = document.querySelector('h1');
  const p = document.querySelector('p');
  return {
    injected: !!document.getElementById(id),
    h1Font: h1 && getComputedStyle(h1).fontFamily,
    pFont: p && getComputedStyle(p).fontFamily,
    h1Text: h1 && h1.textContent
  };
})()

